        break;

      case HAL_SDADC_INJ_CONVERSION_HALF_CB_ID :
        hsdadc->InjectedConvHalfCpltCallback = HAL_SDADC_InjectedConvHalfCpltCallback;
        break;

      case HAL_SDADC_INJ_CONVERSION_COMPLETE_CB_ID :
